/// A DS colour back to 0xRRGGBB (each 5-bit channel widened as (c << 3) | (c >> 2)), for host previews.
pub const fn rgb888(c: u16) -> u32 {
    (widen(c) << 16) | (widen(c >> 5) << 8) | widen(c >> 10)
}

const fn widen(v: u16) -> u32 {
    let v = (v & 31) as u32;
    (v << 3) | (v >> 2)
}
